    useCases: [{"title":"SaaS Sales Teams","description":"Accelerate your SaaS sales cycle with AI-powered lead scoring and automated outreach.","points":["Identify high-intent prospects","Automate multi-touch sequences","Predict deal closure probability"]},{"title":"B2B Sales Operations","description":"Scale your B2B sales without scaling your team.","points":["AI-powered lead qualification","Personalized outreach at scale","Real-time pipeline visibility"]},{"title":"Agency Growth","description":"Help your clients grow their businesses with data-driven insights.","points":["White-label reporting","Multi-account management","Client ROI tracking"]}],
    testimonials: [{"quote":"We increased our qualified leads by 340% in the first quarter using AI Sales Intelligence Pro. The AI knows exactly when and how to reach out. Game-changer for our sales team.","name":"Sarah Martinez","role":"VP of Sales, TechFlow Solutions","avatar":"https://images.unsplash.com/photo-1494790108377-be9c29b29330?ixlib=rb-4.0.3&auto=format&fit=crop&w=150&q=80"},{"quote":"AI Sales Intelligence Pro helped us close deals 42% faster. The automated follow-ups are so personalized that prospects think we have a dedicated assistant just for them.","name":"Michael Chen","role":"CEO, CloudScale Inc.","avatar":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?ixlib=rb-4.0.3&auto=format&fit=crop&w=150&q=80"}],
    faqs: [{"question":"How quickly can I get started with AI Sales Intelligence Pro?","answer":"Most users are up and running within 5 minutes. Simply create an account, connect your data sources, and the AI handles the rest. No technical setup or training required."},{"question":"Is my data secure with AI Sales Intelligence Pro?","answer":"Absolutely. We use enterprise-grade encryption (AES-256) for data at rest and in transit. We're SOC 2 Type II certified and GDPR compliant. Your data is never used to train our models without your explicit consent."},{"question":"Can I integrate AI Sales Intelligence Pro with my existing tools?","answer":"Yes! AI Sales Intelligence Pro integrates with 100+ popular tools including Slack, Google Workspace, Microsoft 365, Salesforce, HubSpot, and many more. We also offer a robust API for custom integrations."},{"question":"What kind of support do you offer?","answer":"We provide 24/7 email support for all users, priority chat support for paid plans, and dedicated account managers for enterprise customers. Our comprehensive documentation and video tutorials help you get the most out of AI Sales Intelligence Pro."},{"question":"Can I cancel my subscription anytime?","answer":"Yes, you can cancel anytime with no penalties. If you're on an annual plan, we'll prorate your refund. We also offer a 14-day money-back guarantee for new users."}],
