  "chat-with-github": {
    longDescription: "Transform the way you work with GitHub Repo Assistant. Explore and understand GitHub repositories with AI chat. Built for professionals and teams who need results fast, this intelligent application combines cutting-edge AI models with practical workflows to deliver retrieval-augmented generation and knowledge management capabilities that actually ship to production.\n\nUnlike generic tools, GitHub Repo Assistant is purpose-built for real-world tasks. Every feature has been designed based on feedback from thousands of users who depend on it daily. Whether you're a solo creator, part of a growing team, or leading enterprise initiatives, GitHub Repo Assistant scales to meet your needs while maintaining the quality and reliability you expect from professional-grade software.\n\nWhat sets GitHub Repo Assistant apart is its focus on outcomes, not just features. The AI doesn't just process inputs—it understands context, learns from your patterns, and proactively suggests improvements. From initial setup to advanced customization, you'll find the experience intuitive, the results consistent, and the impact measurable. Join thousands of professionals who have made GitHub Repo Assistant their go-to solution for retrieval-augmented generation and knowledge management.",
    benefits: ["Find any information in seconds, not minutes","Get accurate answers with source citations","Transform scattered documents into searchable knowledge"],
    features: [{"title":"Intelligent Document Processing","description":"Extract, index, and understand content from PDFs, docs, websites, and more."},{"title":"Semantic Search","description":"Find information by meaning, not just keywords, with advanced vector search."},{"title":"Multi-Source Integration","description":"Connect multiple data sources into a unified, searchable knowledge base."},{"title":"Citation & Source Tracking","description":"Every answer comes with source citations so you can verify information."},{"title":"Conversational Interface","description":"Ask questions in natural language and get accurate, contextual answers."},{"title":"Enterprise Security","description":"Role-based access control, audit logs, and data encryption for enterprise needs."}],
    steps: [{"title":"Set Up Your Account","description":"Create your account in under 2 minutes. No credit card required to get started with GitHub Repo Assistant."},{"title":"Connect Your Data","description":"Integrate with your existing tools or upload your data. We support all major platforms."},{"title":"Configure Your Preferences","description":"Customize the AI to match your specific needs and workflow preferences."},{"title":"Start Getting Results","description":"Begin using GitHub Repo Assistant immediately. The AI learns from your interactions to deliver better results over time."}],
    useCases: [{"title":"Enterprise Teams","description":"Make your company knowledge instantly searchable.","points":["Document indexing","Semantic search","Access control"]},{"title":"Research Organizations","description":"Find relevant research faster.","points":["Paper analysis","Citation tracking","Knowledge graphs"]},{"title":"Customer Support","description":"Empower your support team with instant answers.","points":["Knowledge base search","Ticket deflection","Agent assistance"]}],
    testimonials: [{"quote":"Our team finds information 10x faster with GitHub Repo Assistant. It's like having a research assistant who never sleeps.","name":"Lisa Patel","role":"Knowledge Manager, InfoCorp","avatar":"https://images.unsplash.com/photo-1494790108377-be9c29b29330?ixlib=rb-4.0.3&auto=format&fit=crop&w=150&q=80"},{"quote":"The accuracy of the answers is remarkable. Every response comes with sources, so we can trust the information.","name":"Mark Johnson","role":"CTO, ResearchLab","avatar":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?ixlib=rb-4.0.3&auto=format&fit=crop&w=150&q=80"}],
    faqs: [{"question":"How quickly can I get started with GitHub Repo Assistant?","answer":"Most users are up and running within 5 minutes. Simply create an account, connect your data sources, and the AI handles the rest. No technical setup or training required."},{"question":"Is my data secure with GitHub Repo Assistant?","answer":"Absolutely. We use enterprise-grade encryption (AES-256) for data at rest and in transit. We're SOC 2 Type II certified and GDPR compliant. Your data is never used to train our models without your explicit consent."},{"question":"Can I integrate GitHub Repo Assistant with my existing tools?","answer":"Yes! GitHub Repo Assistant integrates with 100+ popular tools including Slack, Google Workspace, Microsoft 365, Salesforce, HubSpot, and many more. We also offer a robust API for custom integrations."},{"question":"What kind of support do you offer?","answer":"We provide 24/7 email support for all users, priority chat support for paid plans, and dedicated account managers for enterprise customers. Our comprehensive documentation and video tutorials help you get the most out of GitHub Repo Assistant."},{"question":"Can I cancel my subscription anytime?","answer":"Yes, you can cancel anytime with no penalties. If you're on an annual plan, we'll prorate your refund. We also offer a 14-day money-back guarantee for new users."}],
    tags: ["rag","knowledge-base","search","ai","document-processing","enterprise"],
    price: 97,
  },
